fn queue_lookup_is_exact() {
    let mut h = Harness::new();
    create(&mut h, "q");
    for name in ["Q", "q ", "", "q.fifo"] {
        for cmd in ["GetQueueAttributes", "PurgeQueue", "DeleteQueue"] {
            assert_eq!(
