fn ten_entries_are_allowed() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    let entries: Vec<Value> = (0..10)
        .map(|i| json!({"Id": format!("i{i}"), "Body": "x"}))
        .collect();
    let r = h.ok(send_batch("q", json!(entries)));
    assert_eq!(r["Successful"].as_array().unwrap().len(), 10);
}
